const viewer = $('OAuth — public_profile').first().json;
const pages = $input.first().json.data ?? [];
const page = pages.find(p => /virya/i.test(p.name ?? ''))
  ?? pages.find(p => p.instagram_business_account?.id)
  ?? pages[0];
if (!page) throw new Error('OAuth nie zwrócił żadnej zarządzanej strony. Sprawdź pages_show_list i rolę na stronie.');
if (!page.access_token) throw new Error('Brak Page Access Token w /me/accounts. Połącz credential ponownie z wymaganymi scope’ami.');
if (!page.instagram_business_account?.id) throw new Error('Strona nie ma połączonego konta Instagram Business.');
return [{json:{
  viewer_id: viewer.id,
  viewer_name: viewer.name,
  page_id: page.id,
  page_name: page.name,
  page_tasks: page.tasks ?? [],
  ig_user_id: page.instagram_business_account.id,
  ig_username_hint: page.instagram_business_account.username ?? null,
  page_access_token: page.access_token
}}];

const viewer = $('OAuth — public_profile').first().json;
const selected = $('Wybierz zasoby VIRYA').first().json;
const page = $('Facebook Page — pages_read_engagement').first().json;
const instagram = $input.first().json;
return [{json:{
  review_demo: 'SUCCESS',
  permissions_demonstrated: ['public_profile','pages_show_list','pages_read_engagement','instagram_basic'],
  authenticated_person: {id: viewer.id, name: viewer.name},
  selected_managed_page: {id: selected.page_id, name: selected.page_name, tasks: selected.page_tasks},
  facebook_page_data: page,
  connected_instagram_business_account: instagram,
  security: 'No access tokens are included in this final output.'
}}];
